  Lemma lbfA : forall c b nb, 0 <= c < 2^64 -> 0 <= b < 2^31 ->
    Z.land (c ≪ Z.land b 63) 18446744073709551615 ≫ Z.land (Z.land (bv_swrap 32 (0 - nb)) 18446744073709551615) 63
