  Definition ftA_fin (r : res (list Z)) (m2 : amem) (a5v : Z) : Prop :=
    munch WFT m0 m2 /\ wmono asegs m0 m2 /\ mem_inv asegs m2 /\ (exists w, rw_cells asegs m2 (SP1 + 80) [C8 w]) /\
    match r with
    | Ok l => a5v = zlen l /\ exists junk, u8arr asegs m2 DST (map (Z_to_bv 8) l ++ junk) /\ zlen junk = dcap - zlen l
    | Err e => a5v = - e /\ 0 < e < 120
    | Ub | NoFuel => False
    end.
  Definition ftA_K (r : res (list Z)) : Prop :=
    forall m2 a5v (y1 y5 y6 y7 y10 y11 y12 y13 y14 y16 y17 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
      ftA_fin r m2 a5v ->
      evtF asegs RNG Q (TX m2 a5v y1 y5 y6 y7 y10 y11 y12 y13 y14 y16 y17 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31).
  Definition ftA_inv (m1 : amem) (out : list Z) : Prop :=
    (exists junk, u8arr asegs m1 DST (map (Z_to_bv 8) out ++ junk) /\ zlen junk = dcap - zlen out)
    /\ (exists w, rw_cells asegs m1 (SP1 + 80) [C8 w])
    /\ munch WFT m0 m1 /\ wmono asegs m0 m1 /\ mem_inv asegs m1.

  (* [comment removed for export] *)
  Ltac ftA_lin :=
    pose proof atop_range as ATR; pose proof (ablk_lin _ _ HDT) as (HDTa & HDTb & HDTc & HDTd);
    pose proof (ablk_lin _ _ HDST) as (HDSa & HDSb & HDSc & HDSd); pose proof (ablk_lin _ _ HS0) as (HSa & HSb & HSc & HSd);
    unfold AIMG_HI in HDTa, HDSa, HSa.

