  Lemma ftA_x1 : forall out1 s2 dd o1 s2' d' m1 (xra t0 t3 t4 t5 t6 a0 a2 a7 s4 s5 s6 s7 s9 s10 : word),
    decode_sym d true s2 dd = Ok (o1, s2', d') -> 0 <= bd_bits dd <= 2^30 ->
    1 <= zlen out1 -> zlen out1 + 1 <= dcap -> ftA_inv m1 out1 -> ftA_K (Ok (out1 ++ [o1])) ->
    evtF asegs RNG Q (FTS 0x97710 m1 xra t0 t3 t4 t5 t6 a0 (Z_to_bv 64 (DST + zlen out1 - 1)) a2 (Z_to_bv 64 (DST + zlen out1))
                         (Z_to_bv 64 s2) a7 s4 s5 s6 s7 s9 s10).
Proof.
