    ftA_inv m1 out1 -> ftA_K r ->
    evtF asegs RNG Q (FTS 0x9748c m1 xra (Z_to_bv 64 k) (Z_to_bv 64 b0) (Z_to_bv 64 ns1) (Z_to_bv 64 (bd_bits d1r)) (Z_to_bv 64 c0)
